import React, { useState } from 'react';
import './MenuItemsWithOptions.css';

const MenuItemsWithOptions = ({ items, onItemSelect }) => {
  const [selectedOptions, setSelectedOptions] = useState({});

  const formatPrice = (price) => `RM ${price.toFixed(2)}`;

  const getItemOptions = (itemId) => {
    // 메뉴별 옵션 정의
    const optionsMap = {
      1: { // Bulgogi Rice Bowl
        size: [
          { id: 'M', name: 'Regular', price: 0 },
          { id: 'L', name: 'Large', price: 3.00 }
        ],
        spice: [
          { id: 'mild', name: '보통', price: 0 },
          { id: 'hot', name: '매움', price: 0 }
        ]
      },
      2: { // Kimchi Fried Rice
        size: [
          { id: 'M', name: 'Regular', price: 0 },
          { id: 'L', name: 'Large', price: 2.50 }
        ],
        spice: [
          { id: 'mild', name: '보통', price: 0 },
          { id: 'hot', name: '매움', price: 0 },
          { id: 'very-hot', name: '아주매움', price: 0 }
        ]
      }
    };
    return optionsMap[itemId] || {};
  };

  const handleOptionSelect = (itemId, category, optionId) => {
    setSelectedOptions(prev => ({
      ...prev,
      [itemId]: {
        ...prev[itemId],
        [category]: optionId
      }
    }));
  };

  const handleAddToCart = (item) => {
    const options = selectedOptions[item.id] || {};
    const itemWithOptions = {
      ...item,
      selectedOptions: options
    };
    onItemSelect(itemWithOptions);
  };

  return (
    <div className="menu-items-with-options">
      {items.map(item => {
        const options = getItemOptions(item.id);
        const currentOptions = selectedOptions[item.id] || {};

        return (
          <div key={item.id} className="menu-item-card-with-options">
            <div className="menu-item-image">
              <img 
                src={`https://picsum.photos/200/120?random=${item.id}`}
                alt={item.name}
                className="item-photo"
              />
            </div>

            <div className="menu-item-info">
              <h3 className="item-name">{item.name}</h3>
              <p className="item-description">{item.description}</p>

              {/* 사이즈 옵션 */}
              {options.size && (
                <div className="option-group">
                  <span className="option-label">Size:</span>
                  <div className="option-buttons">
                    {options.size.map(size => (
                      <button
                        key={size.id}
                        className={`option-btn ${currentOptions.size === size.id ? 'selected' : ''}`}
                        onClick={() => handleOptionSelect(item.id, 'size', size.id)}
                      >
                        {size.name}
                        {size.price > 0 && ` (+${formatPrice(size.price)})`}
                      </button>
                    ))}
                  </div>
                </div>
              )}

              {/* 맵기 옵션 */}
              {options.spice && (
                <div className="option-group">
                  <span className="option-label">맵기:</span>
                  <div className="option-buttons">
                    {options.spice.map(spice => (
                      <button
                        key={spice.id}
                        className={`option-btn ${currentOptions.spice === spice.id ? 'selected' : ''}`}
                        onClick={() => handleOptionSelect(item.id, 'spice', spice.id)}
                      >
                        {spice.name}
                      </button>
                    ))}
                  </div>
                </div>
              )}

              <div className="item-footer">
                <div className="item-price">{formatPrice(item.price)}</div>
                <button 
                  className="add-to-cart-btn"
                  onClick={() => handleAddToCart(item)}
                >
                  Add to Cart
                </button>
              </div>
            </div>
          </div>
        );
      })}
    </div>
  );
};

export default MenuItemsWithOptions;
